-- =====================================================================
-- 011 · Vocabulario: parejas de 7 palabras y tarjetas con dibujo
--   - Tipo nuevo de ejercicio "dibujo": ves el dibujo y lo dices en inglés
--   - Una lección "Vocabulario" por nivel (1–8) con parejas de 7 y dibujos
--   - Mi camino mete 1 pareja de 7 y 1 dibujo en cada bloque
-- Contenido y dibujos propios. Pega TODO este archivo en Supabase → SQL Editor → Run.
-- Se puede correr varias veces sin dañar nada. Requiere 006–009.
-- =====================================================================

alter table ejercicios drop constraint if exists ejercicios_tipo_check;
alter table ejercicios add constraint ejercicios_tipo_check
  check (tipo in ('elegir','escuchar','ordenar','escribir','emparejar','comprension','decir','libre','rapido','dibujo'));

on conflict (id) do update set titulo = excluded.titulo, descripcion = excluded.descripcion, episodio = excluded.episodio, orden = excluded.orden;

on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;

-- Listo: 8 lecciones, 27 parejas de 7 y 70 dibujos.
